settings.markdownTextFunction:
let controller = ctx.stateController;
let params = controller.getStateParams();
let $injector = ctx.$scope.$injector;
let userService = $injector.get(ctx.servicesMap.get('userService')); 

if (!params.stateId) {
    params.stateId = "locations";
}

controller.updateState('default', params);

if (!localStorage.getItem("role")) {
    userService.getUserInfo(ctx.currentUser.userId).subscribe(response => {
        localStorage.setItem("role", response.groups.some((element) => element.name === "Tenant Administrators") ? "Admin" : "Viewer");
    });
}

return `
    <div tb-toast toastTarget="layout" class="layout" fxLayout="column">
        <div *ngIf="ctx && ctx.stateController" class="stateBlock">
            <tb-dashboard-state class="mainState" *ngIf="ctx.stateController.getStateParams().stateId=='locations'"
                [ctx]="ctx" [syncParentStateParams]="true" stateId="locations">
            </tb-dashboard-state>
            <tb-dashboard-state class="mainState" *ngIf="ctx.stateController.getStateParams().stateId=='locationDetails'"
                [ctx]="ctx" [syncParentStateParams]="true" stateId="locationDetails">
            </tb-dashboard-state>
            <tb-dashboard-state class="mainState" *ngIf="ctx.stateController.getStateParams().stateId=='zoneDetails'"
                [ctx]="ctx" [syncParentStateParams]="true" stateId="zoneDetails">
            </tb-dashboard-state>
        </div>        
    </div>
`;

