    border-radius: 12px!important;
}

.form-wrapper {
    padding: 20px;
    border-radius: 12px;
    border: 1px solid #D0D5DD;
    background: #FCFCFD;
    min-width: 678px;
    overflow: auto;
    max-height: 800px;
}

.form-header-panel {
    display: flex;
    width: 100%;
    justify-content: space-between;
    margin-bottom: 12px;
}

.title {
    color: #0C111D;
    font-size: 28px;
    font-weight: 600;
    line-height: 36px;
}

.first-step-buttons-container {
    width: 100%;
    display: flex;
    justify-content: flex-end;
}

.first-step-buttons-container button:not(:last-child) {
    margin-right: 8px;
}

.buttons-container {
    width: 100%;
    display: flex;
    justify-content: space-between;
}

.row {
    display: flex;
    width: 100%;
    gap: 20px;
}

.row .input-wrapper {
    flex: 1;
}

input, mat-form-field, tb-phone-input  {
    width: 100%;
}

.tb-default .mat-stepper-horizontal, .tb-default .mat-stepper-vertical {
    background-color: transparent;
}

.choose-type-label {
    color: #0C111D;
    font-size: 20px;
    font-weight: 600;
    line-height: 26px;
}

.add-geofence-button-container {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    color: var(--tb-primary-500);
    font-size: 18px;
    font-weight: 500;
    line-height: 28px;
    cursor: pointer;
}

.add-geofence-button {
    display: flex;
    justify-content: center;
    align-items: center;
}

.add-geofence-button-container mat-icon {
    width: 20px;
    height: 20px;
    font-size: 20px;
    color: var(--tb-primary-500);
    margin-right: 4px;
}

hr {
    flex-grow: 1;
    border: 1px solid #D0D5DD;
}

.input-with-button-wrapper {
    display: flex;
    gap: 20px
}

.input-with-button-wrapper .input-wrapper {
    flex: 1;
}

.geofence-button {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 44px!important;
    height: 44px!important;
    border-radius: 4px!important;
    cursor: pointer;
}

.geofence-button mat-icon{
    width: 18px;
