let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap.get('customDialog'));


openAssetsFilterDialog();

function openAssetsFilterDialog() {
    customDialog.customDialog(htmlTemplate, AssetEditDialogController).subscribe();
}

function AssetEditDialogController(instance) {
    const vm = instance;

    vm.allTypesSelected = true;
    vm.allDepartmentsSelected = true;
    vm.allAlertStatusesSelected = true;

    const pageLink = widgetContext.pageLink(1073741824);
    if(!widgetContext.$scope.assetOptions) {
        widgetContext.$scope.assetOptions = [];

        const entityFilter = widgetContext.defaultSubscription.configuredDatasources[0].entityFilter;

        const params = {
            entityFilter,
            pageLink,
            entityFields: [
                {
                    type: "ENTITY_FIELD",
                    key: "name"
                },
                {
                    type: "ENTITY_FIELD",
                    key: "type"
                }
            ],
            latestValues: [
                {
                    type: "ATTRIBUTE",
                    key: "status"
                },
                {
                    type: "ATTRIBUTE",
                    key: "alertActivity"
                }
            ]
        };

        widgetContext.http.post(`/api/entitiesQuery/find`, params)
            .subscribe(response => {
                response.data.forEach(entity => {
                    const latest = entity.latest;

                    const assetOption = {
                        name: latest.ENTITY_FIELD.name.value,
                        type: latest.ENTITY_FIELD.type.value,
                        status: latest.ATTRIBUTE.status.value,
                        alertActivity: latest.ATTRIBUTE.alertActivity.value ? latest.ATTRIBUTE.alertActivity.value : "false" 
                    };

                    widgetContext.$scope.assetOptions.push(assetOption);
                });
            });
    }

    vm.assetTypes = [
        {
            label: "Loader",
            value: "Loader"
        },
        {
            label: "Box",
            value: "Box",
        },
        {
            label: "Worker",
            value: "Worker"
        }, 
        {
            label: "Tool",
            value: "Tool"
        }
    ];

    vm.departmentOptions = [
        {
            label: "Department 1",
            value: "Department 1"
        },
        {
            label: "Department 2",
            value: "Department 2"
        },
        {
            label: "Department 3",
            value: "Department 3"
        }
    ];

    vm.statusOptions = [
        {
            label: "Active",
            value: "true"
        },
        {
            label: "Inactive",
            value: "false"
        }
    ];

    vm.alertStatusOptions = [
        {
            label: "Assets with alerts",
            value: "true"
        },
        {
            label: "Assets without alerts",
            value: "false",
        }
    ];

    vm.filtersFormGroup = vm.fb.group({
        type: [vm.assetTypes.map(option => option.value), []],
        department: [vm.departmentOptions.map(option => option.value), []],
        status: vm.fb.group({
            active: [true, []],
            inactive: [true, []]
        }),
        alertActivity: [vm.alertStatusOptions.map(option => option.value), []]
    });

    if (widgetContext.$scope.filtersFormGroupValue) {
        vm.filtersFormGroup.patchValue(widgetContext.$scope.filtersFormGroupValue);
        const {type, department, alertActivity} = widgetContext.$scope.filtersFormGroupValue;

        vm.allTypesSelected = type.length === vm.assetTypes.length;
        vm.allDepartmentsSelected = department.length === vm.departmentOptions.length;
        vm.allAlertStatusesSelected = alertActivity.length === vm.alertStatusOptions.length;
    }

    vm.toggleAllSelection = function(controlName, options) {
        const controlValue = vm.filtersFormGroup.get(controlName).value;

        const allSelected = controlValue ? controlValue.length === options.length : false;

        vm.filtersFormGroup.get(controlName).setValue(allSelected ? []: options.map(option => option.value));

        switch (controlName) {
            case "type":
                vm.allTypesSelected = !allSelected;
                break;
            case "department":
                vm.allDepartmentsSelected = !allSelected;
                break;
            default: 
                vm.allAlertStatusesSelected = !allSelected;
                break;
        }

        widgetContext.detectChanges();
    };

    vm.onOptionSelected = function(controlName, options) {
        const selectedValues = vm.filtersFormGroup.get(controlName).value;

        const allOptionsSelected = selectedValues.length === options.length;

        if (controlName === "type") {
            vm.allTypesSelected = allOptionsSelected;
        } else if (controlName === "department") {
            vm.allDepartmentsSelected = allOptionsSelected;
        } else {
            vm.allAlertStatusesSelected = allOptionsSelected;
        }
    };

    vm.cancel = function() {
        vm.dialogRef.close(null);
    };

    vm.applyFilters = function() {
        const formValue = vm.filtersFormGroup.value;

        widgetContext.$scope.filtersFormGroupValue = formValue;

        const filteredNames = widgetContext.$scope.assetOptions.filter(option => {
            const hasSuitableType = formValue.type && formValue.type.length
                ? formValue.type.includes(option.type)
                : true;

            const hasSuitableDepartment = true;

            const statuses = [];

            if (formValue.status.active) {
                statuses.push("true");
            }

            if (formValue.status.inactive) {
                statuses.push("false");
            }

            const hasSuitableStatus = statuses.length
                ? statuses.includes(option.status)
                : true;

            const hasSuitableAlertActivity = formValue.alertActivity && formValue.alertActivity.length
                ? formValue.alertActivity.includes(option.alertActivity)
                : true;

            return hasSuitableType && hasSuitableStatus && hasSuitableDepartment && hasSuitableAlertActivity;
        }).map(assetOption => assetOption.name);


        const aliasController = widgetContext.dashboard.aliasController;

        if (aliasController.origFilters) {
            const id = Object.keys(aliasController.origFilters).find((filterId) => 
                aliasController.origFilters[filterId].filter === "Zone assets filter"
            );

            const filtersCopy = Object.assign({}, aliasController.origFilters);
            const condition = filtersCopy[id];
            if(condition && condition.keyFilters.length && condition.keyFilters[0].predicates.length){
                condition.keyFilters[0].predicates[0].keyFilterPredicate.value.defaultValue = filteredNames.length ? filteredNames.join(", ") : "{}";
                aliasController.updateUserFilter(condition);
                widgetContext.updateAliases();
            }
        }

        vm.dialogRef.close(null);
    };
}

