let controller = ctx.stateController;
let params = controller.getStateParams();

const allZonesLabel = "All zones"

let options = [{
    label: allZonesLabel,
    value: null
}];

ctx.selectedZone = null;

ctx.selectZone = function(value, label) {
    if (label !== allZonesLabel) {
        params.selectedZone = {
            entityId: {
                entityType: "ASSET",
                id: value
            },  
            entityName: label
        };
    } else {
        delete params.selectedZone;
    }

    controller.updateState('default', params);
};

ctx.datasources.forEach(datasource => {
    if (datasource.aliasName === "Current Location Zones") {
        options.push({
            label: datasource.entityName,
            value: datasource.entityId
        });
    } else {
        ctx.selectedZone = datasource.entityId;
    }
});

return `
    <div class="zone-selector-container">
        ${options.map(item => {
            const isSelected = item.value === ctx.selectedZone;
            const value = item.value;
            return `<div class="row" [ngClass]="{'active': ${isSelected}}" (click)="ctx.selectZone('${item.value}', '${item.label}')">
                <span class="zoneName" [ngClass]="{ 'active': ${isSelected} }">${item.label}</span>
                <mat-icon *ngIf="${isSelected}">done</mat-icon>
            </div>
            `;
        }).join('')}
    </div>
`;

