    )
    .subscribe(dashboardResponse => {
        const dashboardId = dashboardResponse.data.find(dashboard => dashboard.title === locationsDashboardName).id.id;

        const jsonStr = JSON.stringify([
            {
                id: "default",
                params: {
                    stateId: 'zoneDetails',
                    prevState: 'locationsDetails',
                    subState: 'general',
                    statesArray: [
                        {
                            stateId: 'locations', 
                            name: "Locations"
                        },
                    ],
                    selectedLocation,
                    selectedZone: {
                        entityName,
                        entityId,
                        entityLabel
                    }
                }
            }
        ]);

        const state = btoa(jsonStr);

        const queryParams = {
            stateId: "Locations",
            dashboardId,
            hideDashboardToolbar: true,
            state
        };

        router.navigate(['/iframeView'], {queryParams});
    });

